const string W="D:/project/MTGB/design-demos/battlefield-redesign-2026-10-24/";
var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>();var results=new System.Collections.Generic.List<object>();int checks=0,failed=0;
void Check(bool pass,string context){checks++;if(!pass)failed++;results.Add(new{pass,context});}
ForgeSeatView Sample()=>JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(W+"native-full-seat.json"));
Transform Root()=>GameObject.Find("Canvas").transform;
Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c.Min(v=>v.x),c.Min(v=>v.y),c.Max(v=>v.x),c.Max(v=>v.y));}
bool Click(UnityEngine.UI.Button b){var p=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=Bounds((RectTransform)b.transform).center,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(p,hits);bool hit=hits.Count>0&&hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()==b;if(hit)UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);return hit;}
var assembly=typeof(UnityEditor.Editor).Assembly;var gameViewType=assembly.GetType("UnityEditor.GameView");var gameView=UnityEditor.EditorWindow.GetWindow(gameViewType);var sizeProperty=gameViewType.GetProperty("selectedSizeIndex",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);int savedSize=(int)sizeProperty.GetValue(gameView);var sizesType=assembly.GetType("UnityEditor.GameViewSizes");var sizes=typeof(UnityEditor.ScriptableSingleton<>).MakeGenericType(sizesType).GetProperty("instance").GetValue(null);var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeGroupType"),"Standalone")});var added=new System.Collections.Generic.List<int>();
void Resize(int w,int h){int index=((string[])group.GetType().GetMethod("GetDisplayTexts").Invoke(group,null)).Length;var size=Activator.CreateInstance(assembly.GetType("UnityEditor.GameViewSize"),new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),w,h,"MTGB stack slide UI"});group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});added.Add(index);sizeProperty.SetValue(gameView,index);gameView.Repaint();}
void Save(string status){var method=Type.GetType("Newtonsoft.Json.JsonConvert, Newtonsoft.Json").GetMethod("SerializeObject",new[]{typeof(object)});System.IO.File.WriteAllText(W+"stack-slide-windows-validation.json",(string)method.Invoke(null,new object[]{new{status,checks,failed,results}}));}
void Restore(){sizeProperty.SetValue(gameView,savedSize);foreach(int i in added.OrderByDescending(i=>i))group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{i});}
System.Collections.IEnumerator Run(){
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1024,768)}){
  Resize(size.x,size.y);yield return new WaitForSecondsRealtime(.4f);var v=Sample();ui.Present(v,1,true,_=>{},null,"本地 UI 样本");
  typeof(ForgeBattlefieldController).GetMethod("SetRedesignHandExpanded",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(ui,new object[]{true});
  foreach(string pool in new[]{"ManaPoolChips","PublicManaPool"})Root().Find(pool).GetComponent<BattlefieldHorizontalScroll>().horizontalNormalizedPosition=0;
  foreach(var pointer in Root().Find("PlayerHandRoot").GetComponentsInChildren<ForgeBattlefieldCardPointer>()){pointer.ResetHover();pointer.AllowHandHover=false;}
  yield return new WaitForSecondsRealtime(.6f);Canvas.ForceUpdateCanvases();
  var col=Root().Find("StackColumn") as RectTransform;var rail=Root().Find("RedesignStackControls");var box=Bounds(col);Check(Screen.width==size.x&&Screen.height==size.y,"actual resolution "+size);Check(box.xMin>=0&&box.xMax<=Screen.width&&box.yMin>=0&&box.yMax<=Screen.height,"expanded panel bounds "+size);
  foreach(string name in new[]{"ManaPoolChips","PublicManaPool"}){var mana=Root().Find(name) as RectTransform;var bounds=Bounds(mana);Check(bounds.xMin>=0&&bounds.xMax<=Screen.width&&bounds.yMin>=0&&bounds.yMax<=Screen.height,"mana within window "+name+size);foreach(string plate in new[]{"PlayerPlate/PlayerCounters","OpponentPlate/PlayerCounters","PlayerPlateWithZones","OpponentPlateWithZones"})Check(!bounds.Overlaps(Bounds((RectTransform)Root().Find(plate))),"mana clears player info "+name+plate+size);}
  Check(Click(rail.Find("CollapseStack").GetComponent<UnityEngine.UI.Button>()),"hide reachable "+size);yield return new WaitForSecondsRealtime(.4f);Check(Bounds(col).xMin>Screen.width,"hidden panel beyond screen "+size);ScreenCapture.CaptureScreenshot(W+"stack-slide-hidden-"+size.x+"x"+size.y+".png");yield return new WaitForEndOfFrame();
  Check(Click(rail.Find("CollapseStack").GetComponent<UnityEngine.UI.Button>()),"restore reachable "+size);yield return new WaitForSecondsRealtime(.4f);Check(Mathf.Abs(col.anchoredPosition.x+28)<.1f,"restored endpoint "+size);ScreenCapture.CaptureScreenshot(W+"stack-slide-"+size.x+"x"+size.y+".png");yield return new WaitForEndOfFrame();
 }
 Restore();yield return new WaitForSecondsRealtime(.5f);ui.Present(Sample(),1,false,null,null,"副本 · 只读布局预览");Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int i=0;i<10000;i++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){failed++;results.Add(new{exception=e.ToString()});Restore();Save("ERROR");yield break;}if(!next)break;yield return value;}}
Save("STARTING");ui.StartCoroutine(Guard());return "Actual-window checks started";
